import { Group, Mesh, MeshStandardNodeMaterial, Vector3, Color, PlaneGeometry, SphereGeometry, CylinderGeometry } from 'three/webgpu';
import { uniform, time, vec3, mix, smoothstep, positionWorld, normalWorld, cameraPosition, dot, normalize, reflect, pow, max, abs, sin, cos, length, add, mul, sub, div, clamp, step, texture, uv, color, vec2, vec4, instanceIndex, attribute } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.position.set(2.5, -0.2, 0);
  group.scale.set(1, 1, 1);

  // Load GLB mesh
  const meshGroup = new Group();
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const glbScene = gltf.scene;
    glbScene.traverse((child) => {
      if (child.isMesh) {
        // Ensure PBR material with machined-metal look
        if (child.material) {
          child.material.metalness = 0.55;
          child.material.roughness = 0.5;
          child.material.clearcoat = 0.25;
          child.material.clearcoatRoughness = 0.3;
          child.material.envMapIntensity = 1.2;
          child.material.needsUpdate = true;
        }
      }
    });
    meshGroup.add(glbScene);
  });
  group.add(meshGroup);

  // Capsule label backdrop
  const capsuleGeo = new CylinderGeometry(0.3, 0.3, 0.6, 16, 1, true);
  const capsuleMat = new MeshStandardNodeMaterial();
  capsuleMat.colorNode = color('#0b0b10');
  capsuleMat.metalnessNode = uniform(0.55);
  capsuleMat.roughnessNode = uniform(0.5);
  capsuleMat.clearcoatNode = uniform(0.25);
  capsuleMat.clearcoatRoughnessNode = uniform(0.3);
  capsuleMat.side = 2; // DoubleSide

  const capsule = new Mesh(capsuleGeo, capsuleMat);
  capsule.position.set(0, 0, 0.35);
  capsule.scale.set(1, 0.4, 1);
  group.add(capsule);

  // Accent rim light on capsule
  const rimLight = new Mesh(
    new SphereGeometry(0.35, 16, 8),
    new MeshStandardNodeMaterial({
      color: '#ff2a38',
      emissive: '#ff2a38',
      emissiveIntensity: 1.2,
      transparent: true,
      opacity: 0.3,
      side: 2
    })
  );
  rimLight.position.set(0.3, 0.1, 0.4);
  rimLight.scale.set(0.3, 0.15, 0.1);
  group.add(rimLight);

  // Contact shadow
  const shadowGeo = new PlaneGeometry(0.8, 0.8);
  const shadowMat = new MeshStandardNodeMaterial({
    color: '#000000',
    transparent: true,
    opacity: 0.4,
    side: 2
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -0.35, 0);
  shadow.rotation.x = -Math.PI / 2;
  group.add(shadow);

  // Weighted-settle entrance animation
  const entranceTimeline = gsap.timeline();
  entranceTimeline.from(group.scale, {
    x: 0.96,
    y: 0.96,
    z: 0.96,
    duration: 0.9,
    ease: 'power4.out',
    overwrite: 'auto'
  });
  entranceTimeline.to(group.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.9,
    ease: 'power4.out',
    overwrite: 'auto'
  }, 0.9);
  entranceTimeline.to(group.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
    overwrite: 'auto'
  }, 1.8);

  // Hover rise-in effect
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(group.position, {
    y: group.position.y + 0.15,
    duration: 0.3,
    ease: 'power2.out',
    overwrite: 'auto'
  });

  // Click handler
  group.userData.handlers = {
    pointerover: () => {
      hoverTimeline.play();
    },
    pointerout: () => {
      hoverTimeline.reverse();
    },
    click: () => {
      ctx.emit('hub-journal.select', {});
    }
  };

  // Apply cinematic primitives
  const primitiveCleanups = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      const result = ctx.primitives[prim.name](group, prim.params);
      if (result && result.cleanup) {
        primitiveCleanups.push(result.cleanup);
      }
    });
  }

  // Cleanup
  group.userData.cleanup = () => {
    entranceTimeline.kill();
    hoverTimeline.kill();
    primitiveCleanups.forEach((fn) => fn());
    capsuleGeo.dispose();
    capsuleMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    rimLight.geometry.dispose();
    rimLight.material.dispose();
  };

  return group;
}
